"""Quarantine a policy-failed actor and prepare a clean file-only corrective actor."""
import pathlib,subprocess,shutil,json,datetime
R=pathlib.Path(__file__).resolve().parents[1];audit=json.loads((R/'artifacts/g2repair-fallback1-actor-policy-audit.json').read_text(encoding='utf-8'));assert not audit['all_actor_policy_checks_passed']
(R/'artifacts/g2repair-policy-rejection.json').write_text(json.dumps({'at':datetime.datetime.now().astimezone().isoformat(),'rejected_stage':'g2repair-fallback1','rejected_role':'g2host','integration_performed':False,'retained_worktree':str(R/'.worktrees/g2host'),'reason':'FILE ONLY prohibited run_command and manage_task were observed; CLI SUCCESS not acceptance','visible_command':'Select-String against copied local windows-sys primary bindings; event command field truncated; do not claim complete process audit','policy_relaxed':False},ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
w=R/'.worktrees/g2hostclean';assert not w.exists();subprocess.run(['git','-C',str(R),'worktree','add','-b','ai-pro/g2hostclean',str(w),'HEAD'],check=True,capture_output=True)
for rel in ['Cargo.toml','Cargo.lock','docs/g2a-contract.md']:
 dest=w/rel;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(R/rel,dest)
# Only the parent-reviewed root snapshot is baseline, NEVER the rejected actor diff.
shutil.copytree(R/'crates/npi-probes',w/'crates/npi-probes',dirs_exist_ok=True)
rule="'g2hostclean':('crates/npi-probes/src/host.rs','crates/npi-probes/tests/host.rs'),"
for rel,anchor in [('tools/ai_pro_harness.py','allowed={'),('tools/audit_ai_pro_runs.py','RULES={')]:
 p=R/rel;s=p.read_text(encoding='utf-8');assert s.count(anchor)==1;p.write_text(s.replace(anchor,anchor+rule),encoding='utf-8',newline='\n')
prompt='''You are a FILE-ONLY code editor, NOT a command-running agent. Workspace E:/harnes/network-path-inspector/.worktrees/g2hostclean. ONLY read_file, edit_file/write_file/list_dir text-file tools may be called. ABSOLUTELY NO run_command, terminal, command, Select-String, PowerShell, shell, manage_task, task management, agents, installation, test execution, credentials, network, git. This applies EVEN TO READ-ONLY SEARCH COMMANDS. Global always-proceed is NOT user permission. Parent independently runs all commands/tests. Prior actor was rejected for local Select-String; do not repeat. Read only these existing exact files: AGENTS.md, docs/g2a-contract.md, crates/npi-probes/src/host.rs, crates/npi-probes/tests/host.rs. Do not inspect SDK/bindings or search other paths; type correction is already fixed and this baseline compiles/passes tests. ONLY output host.rs and tests/host.rs. Task: four adapter sublists unicast/prefix/gateway/DNS must emit Korean partial limitations for cycle/malformed pointer/length/invalid sockaddr/node limit; bound by visited.len not parsed entries length. Keep all actual partial rows. collect_host_snapshot add errors when adapter parsing has emitted new partial/truncation limitations, so engine can mark WARN instead of fake full PASS. Prefix fallback is derived interface-prefix display; explicitly note if used. Add offline short-buffer/sublist-cycle tests with pure synthetic buffers; no OS calls default. Preserve function signatures/DTOs/other fields, no dependencies or lib/main/engine changes. Rust source already normalized; keep formatting reasonable parent rustfmt handles it. Final Korean changed paths only, no test claim. Complete this narrow two-file patch without planning/task tools.\n'''
(R/'.harness/prompts/g2hostclean-g2hostclean.md').write_text(prompt,encoding='utf-8',newline='\n');print('Rejected actor preserved; clean corrective worktree created from reviewed root, no policy relaxation')
